using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using MapSharedProps.EditorTools;
public static class FibreFinishChecks {
 [Serializable]class Result{public bool pass;public string error;public List<string> checks=new List<string>();}
 public static void Run(){var args=Environment.GetCommandLineArgs();string source=args[Array.IndexOf(args,"-props-export")+1],output=args[Array.IndexOf(args,"-props-output")+1];Directory.CreateDirectory(output);var result=new Result();int code=0;try{UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);var rd=ScriptableObject.CreateInstance<UnityEngine.Rendering.Universal.UniversalRendererData>();var rp=UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset.Create(rd);GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);var sun=new GameObject("Proof sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.1f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(-5,-9,-4));var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.localScale=Vector3.one*3;floor.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Universal Render Pipeline/Lit"));floor.GetComponent<Renderer>().sharedMaterial.SetColor("_BaseColor",new Color(.22f,.17f,.11f));var camera=new GameObject("Proof camera").AddComponent<Camera>();camera.gameObject.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();camera.fieldOfView=50;camera.aspect=1.28f;camera.backgroundColor=Color.black;camera.clearFlags=CameraClearFlags.SolidColor;camera.targetTexture=new RenderTexture(1280,1000,24,RenderTextureFormat.ARGB32);var data=SmallPropsV1.Read(Path.Combine(source,"small_props.json"));var built=MapSharedPropsBuilder.Build(source);Verify(data,built,source,output,camera,(name,pass,detail)=>{if(!pass)throw new Exception(name+": "+detail);result.checks.Add(name);});result.pass=true;AssetDatabase.SaveAssets();}catch(Exception e){result.error=e.ToString();Debug.LogException(e);code=1;}finally{File.WriteAllText(Path.Combine(output,"fibre-report.json"),JsonUtility.ToJson(result,true));EditorApplication.Exit(code);}}

 public static void Verify(SmallPropsV1.Data data,MapSharedPropsBuilder.Result built,string source,string output,Camera camera,Action<string,bool,string> verify){
  var prior=PreFibreSmallPropsV1.Read(Path.Combine(source,"small_props.json"));verify("unchanged pre-fibre reader retains all 43 assets",prior.assets.Length==43,"");var folder=AssetDatabase.GenerateUniqueAssetPath("Assets/PreFibreProof");AssetDatabase.CreateFolder("Assets",Path.GetFileName(folder));var root=new GameObject("Pre-fibre reader proof");var prefabs=new Dictionary<string,GameObject>();int placed=PreFibreSmallPropsV1.Build(source,folder,root.transform,Shader.Find("MapSharedProps/Lit"),prefabs);int expected=Array.FindAll(File.ReadAllLines(Path.Combine(source,"props.csv")),line=>{var p=line.Split(',');return p.Length==11&&prefabs.ContainsKey(p[1]);}).Length;verify("pre-fibre reader builds all 43 plus presentation without new schema",prefabs.Count==43&&placed==expected,"");root.SetActive(false);
  foreach(var a in data.assets){var now=built.prefabs[a.id];var before=prefabs[a.id];verify(a.id+" frozen-reader root mesh cache reference",now.GetComponent<MeshFilter>().sharedMesh==before.GetComponent<MeshFilter>().sharedMesh,"");var nc=now.GetComponent<MeshCollider>();var bc=before.GetComponent<MeshCollider>();verify(a.id+" frozen-reader collision cache reference",(!nc&&!bc)||(nc&&bc&&nc.sharedMesh==bc.sharedMesh),"");bool fibre=a.id=="tiedsack"||a.id=="coiledrope";verify(a.id+" fibre shader is limited to exactly two existing IDs",(now.GetComponent<Renderer>().sharedMaterial.shader.name=="MapSharedProps/FibreProp")==fibre,"");if(!fibre)continue;var mat=now.GetComponent<Renderer>().sharedMaterial;verify(a.id+" opaque fibre shader compiles",mat.shader.isSupported&&!ShaderUtil.ShaderHasError(mat.shader)&&mat.renderQueue<2500&&mat.GetFloat("_FibreKind")==(a.id=="coiledrope"?1:0),"");var tx=mat.GetTexture("_BaseMap");string texturePath=tx?AssetDatabase.GetAssetPath(tx):"";verify(a.id+" no renderer collider imported texture or light additions",now.GetComponentsInChildren<Renderer>().Length==1&&now.GetComponentsInChildren<Collider>().Length==(a.radius>0?1:0)&&now.GetComponentsInChildren<Light>().Length==0&&!texturePath.StartsWith("Assets/"),"texture="+(tx?tx.name:"none")+", path="+texturePath);var uv=now.GetComponent<MeshFilter>().sharedMesh.uv;bool exact=uv.Length==a.uv.Length/2;float maxU=0;for(int k=0;k<uv.Length;k++){exact&=uv[k].x==a.uv[k*2]&&uv[k].y==a.uv[k*2+1];maxU=Mathf.Max(maxU,Mathf.Abs(uv[k].x));}verify(a.id+" metric fibre UV preserved without image flip",exact&&maxU>1,"");}
  var args=Environment.GetCommandLineArgs();foreach(var flag in new[]{"-props-custom-fibre","-props-custom-fibre-sack"}){int at=Array.IndexOf(args,flag);if(at<0)continue;string customSource=args[at+1],id=flag=="-props-custom-fibre"?"coiledrope":"tiedsack";var customData=SmallPropsV1.Read(Path.Combine(customSource,"small_props.json"));var oldCustom=PreFibreSmallPropsV1.Read(Path.Combine(customSource,"small_props.json"));verify(id+" custom output retains canonical old19/43 library read",customData.assets.Length==43&&oldCustom.assets.Length==43,"");bool unresolved=false;try{FibrePrefabImport.Validate(customSource);}catch(InvalidDataException e){unresolved=e.Message.Contains("External fibre prefab unresolved")&&e.Message.Contains("custom/night-"+id);}verify(id+" custom without an explicit prefab fails visibly before import",unresolved,"");}
  int ropes=0;var rope=Array.Find(data.assets,a=>a.id=="coiledrope");foreach(var line in File.ReadAllLines(Path.Combine(source,"props.csv"))){var row=line.Split(',');if(row.Length!=11||row[1]!="coiledrope")continue;var o=built.root.transform.Find(row[0]);var uv=o.GetComponent<MeshFilter>().sharedMesh.uv;bool exact=uv.Length==rope.uv.Length/2;for(int k=0;k<uv.Length;k++)exact&=uv[k].x==rope.uv[k*2]&&uv[k].y==rope.uv[k*2+1];verify(row[0]+" grounded rope retains full metric UV",exact,"");ropes++;}verify("all three grounded rope placements retain finish UV",ropes==3,"");
  foreach(Transform child in built.root.transform)child.gameObject.SetActive(false);camera.nearClipPlane=.02f;var rt=camera.targetTexture;
  foreach(var id in new[]{"tiedsack","coiledrope","ruinwall"}){var o=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[id]);var a=Array.Find(data.assets,x=>x.id==id);o.transform.position=Vector3.down*a.groundSink;foreach(var view in new[]{"near","angled","multiple"}){var extras=new List<GameObject>();if(view=="multiple")for(int k=0;k<2;k++){var q=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[id]);q.transform.position=new Vector3((k==0?-1:1)*(id=="ruinwall"?3.4f:.8f),-a.groundSink,.2f);q.transform.rotation=Quaternion.Euler(0,k==0?-20:20,0);extras.Add(q);}float distance=id=="ruinwall"?(view=="multiple"?15:6.1f):view=="multiple"?4:1.65f;float target=a.height*.42f;camera.transform.position=new Vector3(distance*.6f,target+distance*(view=="angled"?.95f:.35f),-distance*.8f);camera.transform.rotation=Quaternion.LookRotation(new Vector3(0,target,0)-camera.transform.position);for(int captureWarm=0;captureWarm<3;captureWarm++)camera.Render();var before=RenderTexture.active;RenderTexture.active=rt;var png=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);png.Apply();File.WriteAllBytes(Path.Combine(output,id+"-fibre-"+view+".png"),png.EncodeToPNG());UnityEngine.Object.DestroyImmediate(png);RenderTexture.active=before;foreach(var q in extras)UnityEngine.Object.DestroyImmediate(q);}UnityEngine.Object.DestroyImmediate(o);}
 }
}
